SELECT rt.Name 
FROM RoomTypes rt LEFT JOIN RoomTypeFacilities rtf ON rt.Id = rtf.RoomTypeId 
WHERE rtf.RoomTypeId IS NULL;

SELECT r.RoomNumber
FROM Rooms r LEFT JOIN Stays s ON r.RoomNumber = s.RoomNumber 
WHERE s.Id IS NULL;

SELECT s.Id 
FROM Stays s LEFT JOIN Bookings b ON s.BookingId = b.Id 
WHERE b.id IS NULL;

SELECT id, product_code, product_name
 FROM products
 WHERE list_price <  standard_cost;

SELECT * 
FROM miniwind.orders
WHERE order_date > '2007-01-01';
